insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37bff0df-2454-418b-b50a-db2845245a4e', 'de', 'Warum klappt das Flirten besser, wenn du dich auf den Spaß konzentrierst?', '["Es nimmt die Hintergedanken raus", "Du bist präsenter und entspannter", "Du wirst unabhängig vom Ergebnis", "Es stellt in den Vordergrund, dass du dich beweisen musst"]'::jsonb, 'Wenn du den Moment genießt, ist er selbst schon der Erfolg, nicht das Ergebnis.')
