insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eee49a49-b918-4f25-9827-edc1a9f9bdc0', 'de', 'Welche Signale zeigen, dass du dich eher zurückhalten solltest, statt weiterzugehen?', '["Ein neutraler Ton", "Knappe Antworten", "Keine Gegenfragen", "Echtes Lachen"]'::jsonb, 'Wenn sie deine Energie nicht erwidert, hat sich das Gespräch noch nicht geöffnet.')
