insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ae2493f-bf71-457d-8f09-996e6cf2b464', 'de', 'Was bedeutet Respekt beim Flirten?', '["Ihr Wohlgefühl und ihre Grenzen wichtiger nehmen als dein Ergebnis", "Das ganze Gespräch über selbstbewusst sein", "Sie als ebenbürtig behandeln, ohne zu aggressiv zu sein"]'::jsonb, 'Ein Flirt bleibt respektvoll, wenn dir ihr Wohlgefühl wichtiger ist als dein Erfolg.')
