insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df3d8e11-15af-468e-ba4a-9cca550456d2', 'de', 'Wie schützt du am saubersten euch beide, wenn das Interesse nicht gegenseitig ist?', '["Früh und höflich gehen", "Einen Witz machen, um den Moment aufzulockern", "Leicht nachhaken, um sicherzugehen", "Warten, bis sie direkt Nein sagt"]'::jsonb, 'Ein früher, respektvoller Abschied hält den Moment leicht und erspart euch beiden Unbehagen.')
