insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999e00ac-a18d-4b94-b3a8-e5c97c457f07', 'de', 'Warum zählt gute Energie mehr als Sprüche?', '["Menschen erinnern sich eher an Gefühle als an Inhalte", "Anziehung ist hauptsächlich optisch", "Worte werden beim Flirten überschätzt", "Selbstbewusstsein ersetzt das Gespräch"]'::jsonb, 'Was hängen bleibt, ist das Gefühl. Worte sind zweitrangig gegenüber dem, wie sich der Moment anfühlt.')
