insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8695e9b-bb41-43c3-bf69-51511a2d5917', 'de', 'Sie erzählt, dass sie total auf Yoga steht und sehr beweglich ist. Wie kannst du Humor einsetzen?', '["Ernsthaft die gesundheitlichen Vorteile von Yoga aufzählen", "Von deiner eigenen Yoga-Routine erzählen", "Fragen, wie lange sie schon Yoga macht", "Verspielt fragen, ob sie mit den Fingern an die Zehen kommt"]'::jsonb, 'Leichtes Necken schafft verspielte Energie und lädt zum Schlagabtausch ein.')
