insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63acae8c-e04a-4fc9-98cb-693c477cc5f0', 'de', 'Was macht kleine, lustige Herausforderungen wirksam?', '["Sie darf ehrgeizig sein und Persönlichkeit zeigen", "Jeder Ausgang gibt euch einen Grund weiterzumachen", "Aus Fragen beantworten wird echtes Spielen", "Alle oben genannten"]'::jsonb, 'Kleine Herausforderungen laden zum Spielen ein, zeigen Persönlichkeit und halten das Gespräch lebendig.')
