insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ce27a06-8ab6-4d7f-9ede-e0cfb8108698', 'de', 'Sie fragt: „Wie alt bist du?“ Was könntest du als lustige Herausforderung sagen?', '["Direkt dein genaues Alter sagen", "Sagen, dass Alter keine Rolle spielt", "Die Frage ignorieren", "„Wie alt sehe ich denn aus? Rate mal.“"]'::jsonb, 'Mach ein verspieltes Ratespiel daraus, das schafft gemeinsame Spannung und Schlagabtausch.')
