insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b1b5eb-51d6-4bae-82e9-d9b516852a92', 'de', 'Wann funktioniert Frechsein, und wann kränkt es?', '["Wärme in der Art: Das Lächeln zeigt, dass du nur spielst", "Der Ton zählt mehr als die Worte", "Ein leichter, überraschender Blickwinkel, nicht gemein oder wertend", "Alle oben genannten"]'::jsonb, 'Frechsein funktioniert, wenn Wärme, Ton und Leichtigkeit zeigen, dass es ein Spiel ist und kein Urteil.')
