insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c04e3fb3-07b8-49cb-9664-d35c6a113928', 'de', 'Sie sagt: „Ich komm immer zu spät.“ Was könntest du darauf sagen?', '["„Gut, dass ich immer geduldig bin.“", "„Ist doch okay, keiner ist perfekt.“", "„Warum kommst du zu spät?“", "„Ich bin meistens pünktlich.“"]'::jsonb, 'Eine freche Antwort mit einem Lächeln lädt sie ein, locker mitzuspielen.')
