insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a5612de-f9a6-4bc1-bcbb-29d29d0b1f91', 'de', 'Sie spricht im Gespräch leise und langsam. Woran solltest du dich anpassen?', '["Lauter werden, um ihr Energie zu geben", "Bei deiner lauten Stimme bleiben", "Schnell sprechen, um den Schwung zu halten", "Leiser und langsamer sprechen"]'::jsonb, 'Wenn du dich ihrer Energie und ihrem Ton anpasst, entsteht unbewusst eine Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dc61f4a-f296-4e9b-ae8f-01bd4a923b88', 'de', 'Woran erkennst du, dass sie dich vielleicht spiegelt?', '["Sie nimmt eine ähnliche Haltung ein, nachdem du deine geändert hast", "Sie passt sich deinem Sprechtempo an", "Sie stellt mehr Fragen", "Sie dreht ihren Körper zu dir"]'::jsonb, 'Wenn ihr euch körperlich und in der Energie angleicht, zeigt das oft Wohlgefühl und Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('525d7416-b2f1-4458-807f-26c8a8bd7bc8', 'de', 'Was ist der Hauptzweck von Berührung beim Flirten?', '["So schnell wie möglich körperlich weitergehen", "Ihre Grenzen testen", "Eine bestehende emotionale Verbindung verstärken", "Das Gespräch ersetzen"]'::jsonb, 'Berührung wirkt, wenn sie eine Verbindung unterstützt, die schon da ist, nicht wenn sie eine erzeugen soll.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5136a469-f474-4b76-bc20-841071ccf772', 'de', 'Sie redet weiter gern mit dir, erwidert Berührungen aber nie und scheint sie nicht zu wollen. Was solltest du tun?', '["Mehr berühren, um ihren Widerstand zu brechen", "Sie direkt fragen, warum sie nicht darauf eingeht", "Auf Berührung verzichten und beim Reden bleiben", "Das Gespräch sofort beenden"]'::jsonb, 'Wenn sie Berührung nicht erwidert, ist sie noch nicht willkommen. Pass dich an, ohne etwas zu erzwingen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efe69dc3-5d6a-4f17-b046-2263cec2230f', 'de', 'In welchen Momenten passt eine leichte Berührung?', '["Wenn sie sich vorlehnt oder nah bei dir bleibt", "Wenn sie kurz und höflich antwortet", "Wenn ihr euch gemeinsam durch einen Raum bewegt"]'::jsonb, 'Berührung sollte zu Offenheit und gemeinsamem Schwung passen, nicht zu Neutralität oder Desinteresse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('249a63f3-79dc-45b1-b433-50465a7a107d', 'de', 'Warum dreht Disqualifizieren die übliche Dynamik beim Flirten um?', '["Es zeigt, dass du ihr nicht hinterherläufst und dich nicht zu sehr reinhängst", "Es zeigt, dass du eigene Ansprüche hast", "Es schafft Gleichgewicht statt einseitigen Werbens", "Alle oben genannten"]'::jsonb, 'Disqualifizieren macht aus „sie erwartet Bestätigung“ ein gegenseitiges Auswählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95ad96b3-d2ef-411c-b521-ec1a1bc7d496', 'de', 'Sie erzählt, wie oft sie wegen Instagram erkannt wird. Womit behältst du deinen Rahmen?', '["„Wow, du musst echt beliebt sein.“", "„Soll ich dich dann um ein Autogramm bitten?“", "„Wie viele Follower hast du?“", "„Du hast die ganze Aufmerksamkeit verdient.“"]'::jsonb, 'Leichter Widerspruch zeigt, dass du nicht automatisch beeindruckt bist, und dreht die Dynamik um.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7440e677-e76b-4b16-a0f9-213ae82c821a', 'de', 'Welche Sätze sind Beispiele für gesundes Disqualifizieren?', '["„Da musst du mich schon überzeugen.“", "„Das ist nicht beeindruckend.“", "„Ich weiß nicht, ich bin schwer zu haben.“", "„So besonders bist du nicht.“"]'::jsonb, 'Disqualifizieren soll leicht herausfordern, nie abwerten oder herabsetzen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a91f07b0-5946-49ce-804d-b862552b9592', 'de', 'Was hilft, in einer Begegnung knisternde Spannung zu erzeugen?', '["Tiefe Themen", "Klare, vorhersehbare Freundlichkeit", "Ständige Rückversicherung", "Offenheit darüber, was du eigentlich willst"]'::jsonb, 'Spannung entsteht aus Möglichkeit. Wenn eine Absicht nur angedeutet und nicht ausgesprochen wird, schärft sich die Aufmerksamkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('93982613-1848-48bb-b22b-59bd8c12b62f', 'de', 'Was hilft, knisternde Spannung zu erzeugen?', '["Den Blickkontakt einen Moment länger halten, als es angenehm ist", "Eine Berührung an ihrem Arm kurz andauern lassen, wenn sie es sichtlich genießt", "Etwas näher stehen, solange sie entspannt bleibt", "Alle oben genannten"]'::jsonb, 'Spannung entsteht durch kleine, bewusste Momente von Nähe und Innehalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67379ba9-deb9-45a2-b30c-f9b26b01536d', 'de', 'Welche Sätze bringen wahrscheinlich Spannung rein?', '["„Coole Meinung.“", "„Ich versuch, dich nicht anzustarren, aber du machst es mir schwer.“", "„Wenn du über Dinge redest, die du liebst, sprühst du richtig.“", "„Warum hast du dir den Drink ausgesucht?“"]'::jsonb, 'Verspielt zuzugeben, dass sie dich berührt, oder einen Funken zu benennen, deutet Anziehung an, ohne zu offensichtlich zu sein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43a061f7-1ccd-4592-8e5d-035717e37189', 'de', 'Was ist der Hauptzweck eines Rückbezugs oder Insiderwitzes im Gespräch?', '["Intelligenz und ein gutes Gedächtnis zeigen", "Ein stockendes Gespräch neu starten", "Einen roten Faden und eine gemeinsame Verbindung schaffen", "Etwas wiederholen, das sie gesagt hat, damit es klar ist"]'::jsonb, 'So entsteht das Gefühl einer gemeinsamen Geschichte, und aus Fremden werden Eingeweihte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('344744cd-ace9-45d2-96db-317d056f2f2f', 'de', 'Was macht Rückbezüge wirksam?', '["Sie bauen mit Humor oder einer verspielten Wendung auf einem Detail auf", "Sie schaffen einen roten Faden statt zusammenhangloser Themen", "Das Gespräch fühlt sich an, als würde es sich entwickeln, statt nur dahinzuplätschern", "Alle oben genannten"]'::jsonb, 'Wer sich erinnert fühlt, fühlt sich gesehen, und das vertieft Vertrautheit und Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a584c7b-29ae-4ef4-8faf-ee465bb72e66', 'de', 'Welche Momente eignen sich gut für einen Rückbezug oder Insiderwitz?', '["Kleine Witze, die sie gemacht hat", "Kleine Vorlieben oder Macken, die sie erwähnt hat", "Persönliche Probleme", "Lockere Meinungen oder Übertreibungen"]'::jsonb, 'Rückbezüge funktionieren am besten mit leichten, verspielten oder für sie typischen Details.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0395cf63-6575-4c9c-aaa2-83805005ade7', 'de', 'Sie sagt, sie kann super Sternzeichen erraten. Wie machst du daraus eine lustige Herausforderung?', '["Ihr direkt dein Sternzeichen sagen", "Sagen, dass Astrologie Quatsch ist", "Ernsthaft fragen, warum sie daran glaubt", "„Na los, rat meins.“"]'::jsonb, 'Lad sie zu einem verspielten Ratespiel ein, das schafft gemeinsame Spannung und Schlagabtausch.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('061b4ffe-6aea-49da-b29e-1976fc8c62a3', 'de', '„Was bestellst du?“ oder „Wetten, ich errate, was du bestellst?“ Was schafft mehr Chemie?', '["Das Erste: Es zeigt echtes Interesse an ihren Vorlieben", "Das Zweite: Die verspielte Herausforderung bringt sie rein und macht Spaß", "Das Erste: Es baut besser eine Verbindung auf", "Das Zweite: Es zeigt Selbstbewusstsein"]'::jsonb, 'Ein Ratespiel ist eine verspielte Herausforderung, bei der sie mitmachen muss, und das schafft Energie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0640bea3-7134-4d3d-bbd1-a2dd404d8c97', 'de', 'Sie rückt beim Lachen näher. Was ist die beste Reaktion?', '["Erstarren, um nichts falsch zu deuten", "Zurücktreten, um auf Nummer sicher zu gehen", "Ruhig ihre Nähe erwidern", "Das Thema wechseln"]'::jsonb, 'Wenn du ihre Bewegung erwiderst, bleibt ihr im Einklang, und es fühlt sich angenehm an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dcb3ce2-da4e-48c3-8c5b-7ded4177d531', 'de', 'Sie zieht dich zurück auf, weil du schlecht kochst. Was könntest du als Nächstes tun?', '["Dich verteidigen und rechtfertigen", "Schnell das Thema wechseln", "Lachen und verspielt auf ihrem Necken aufbauen", "Sie ernsthafter aufziehen"]'::jsonb, 'Gegenseitige Verspieltheit zeigt Sicherheit und baut Chemie auf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f0fa46d-8699-4a6c-9b7b-2fe8afa91fe5', 'de', 'Sie erzählt begeistert von ihrem ungewöhnlichen Hobby. Welches Kompliment passt am besten?', '["„Du bist einzigartig.“", "„Ich mag, wie leidenschaftlich du dabei bist, das merkt man richtig.“", "„Du hast coole Interessen.“", "„Du bist attraktiv, wenn du begeistert bist.“"]'::jsonb, 'Konkret darauf bezogen, wie sie ihre Leidenschaft zeigt. Das zeigt, dass du ihre Energie schätzt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14f120e4-9b66-4b46-81d5-b125235fb2f5', 'de', 'Wie unterscheidet sich knisternde Spannung von einem freundschaftlichen Gespräch?', '["Sie lebt von ernsten Themen und tiefem Austausch", "Sie vermeidet nonverbale Signale und Pausen", "Sie bringt eine leise Ungewissheit darüber, was der andere will", "Sie hält die Dynamik völlig vorhersehbar"]'::jsonb, 'Der Funke entsteht, wenn du mehr andeutest, ohne alles klarzumachen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17429248-a6f9-42cf-a924-9553dec0b010', 'de', 'Was macht aus denselben Worten etwas Flirtendes statt nur Nettes?', '["Langsamer und mit weicherer Stimme sprechen", "Schnelles Tempo und abgewandter Blick", "Mit einem Lächeln Blickkontakt halten", "Den Moment danach wirken lassen"]'::jsonb, 'Präsenz und Timing laden die Worte auf, ohne den Inhalt zu ändern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1bcaa8b7-9201-4ec7-bab9-cd622fb9b421', 'de', 'Welche Sätze bringen wahrscheinlich Spannung rein?', '["„Du hast eine ruhige Ausstrahlung, das gefällt mir.“", "„Spannend, erzähl mehr.“", "„Und, was machst du beruflich?“", "„Ich mag, wie du Blickkontakt hältst.“"]'::jsonb, 'Beobachtungen zu ihrer Ausstrahlung oder zur Anziehung zeigen deine Absicht, ohne sie aufzudrängen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e531297-8fe5-432d-9e8a-8bb1970f99ba', 'de', 'Warum hat längerer Blickkontakt eine so starke körperliche Wirkung?', '["Er zeigt ganz natürlich soziale Dominanz", "Er setzt Oxytocin frei, erhöht den Puls und weckt Gefühle von Nähe", "Er schafft Verletzlichkeit, die eine emotionale Verbindung aufbaut"]'::jsonb, 'Der Körper reagiert zuerst auf den Blickkontakt und sendet ganz natürlich mehr Signale von Nähe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e723f5c-f299-44f4-844c-f7190b8f4c42', 'de', 'Das Gespräch läuft gut, und sie hält länger Blickkontakt als sonst. Was solltest du tun?', '["Ihn unterbrechen, um eine Frage zu stellen", "Ihn mit einem kleinen Lächeln erwidern und den Moment wirken lassen", "Wegschauen, um ihr Raum zu geben", "Übertrieben starren, um schnell weiterzugehen"]'::jsonb, 'Einen längeren Blick zu erwidern schafft Nähe ohne Worte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bcd40a3-8939-4555-8f99-7c394079b7a0', 'de', 'Warum schaffen konkrete Komplimente zu etwas, das sie selbst gewählt hat, eine stärkere Verbindung?', '["Sie fühlen sich wie echte Anerkennung ihrer Mühe an", "Sie zeigen, dass dir etwas aufgefallen ist, das sie selbst in der Hand hat", "Sie bewerten direkt ihr Aussehen"]'::jsonb, 'Sie fühlt sich für das gesehen, was sie ist, nicht für das, was ihr in die Wiege gelegt wurde.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d067124-8ee8-41b8-b580-f480159f861e', 'de', 'In einer Gesprächspause schaut sie dir direkt in die Augen. Was solltest du tun?', '["Schnell wegschauen, um Peinlichkeit zu vermeiden", "Sie ohne Lächeln intensiv anstarren", "Nach unten schauen und weiterreden", "Sanft lächeln und ihren Blick ruhig halten"]'::jsonb, 'Sie bietet dir einen längeren Blick an. Erwidere ihn, statt ihn nervös abzubrechen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fc0d39c-22da-4308-8ee9-4ab4c88299d2', 'de', 'Welche Überzeugung hilft am meisten, respektvoll zu flirten?', '["„Wenn ich nicht dränge, verpasse ich Chancen.“", "„Eine Abfuhr heißt, dass ich was falsch gemacht hab.“", "„Selbstbewusstsein heißt, nie einen Rückzieher zu machen.“", "„Nicht jede Begegnung soll weitergehen.“"]'::jsonb, 'Respekt beginnt damit, zu akzeptieren, dass Desinteresse normal ist und kein persönliches Versagen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('34e3a8a0-43de-4673-af81-d73381d0ceba', 'de', 'Sie sagt, sie erkennt super, woher Leute kommen. Was könntest du als lustige Herausforderung tun?', '["Ihr direkt sagen, woher du kommst", "Ihr Talent loben", "Ernsthaft nach ihren Reisen fragen", "„Beweis es. Rat mal, woher ich komme.“"]'::jsonb, 'Lad sie zu einem verspielten Ratespiel ein, das bringt euch beide rein und lädt zum Necken ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36c3a4cc-1b9f-42ea-a62f-551942c80f5d', 'de', 'Was macht eine kleine Herausforderung beim Flirten wirksam?', '["Es geht um nichts, aber es bietet viel Stoff für Schlagabtausch", "Es steht viel auf dem Spiel, und du musst dich beweisen", "Ihr Wissen ernsthaft auf die Probe stellen", "Einer gewinnt eindeutig"]'::jsonb, 'Wenn wenig auf dem Spiel steht, bleibt es lustig, und jeder Ausgang stärkt die Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37dce606-feeb-4072-baf2-17e1f94a6f8e', 'de', 'Sie macht eine kluge Beobachtung über die Leute im Café. Was könntest du darauf sagen?', '["„Du hast schöne Augen.“", "„Du siehst heute toll aus.“", "„Du bist witzig.“", "„So hab ich das noch nie gesehen. Ist mir gar nicht aufgefallen.“"]'::jsonb, 'Das knüpft direkt an ihre Sicht an, und sie fühlt sich wirklich gesehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('384c4054-61db-4bdb-b2c8-91998d08cbee', 'de', 'Was kann längerer Blickkontakt bewirken?', '["Ein stärkeres Gefühl von Nähe", "Körperliche Erregung", "Er zeigt klar Interesse", "Sozialen Druck, etwas sagen zu müssen"]'::jsonb, 'Blickkontakt zeigt Interesse ohne Worte, ohne eine Antwort zu erzwingen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d71381-3505-4e35-9880-fe45c1d756bb', 'de', 'Warum stärken Rückbezüge oder Insiderwitze die Verbindung im Gespräch?', '["Sie spinnen einen Faden, den nur ihr zwei kennt", "Sie zeigen, dass du wirklich zugehört hast", "Sie schaffen gemeinsame Bezüge und Vertrautheit", "Alle oben genannten"]'::jsonb, 'Rückbezüge machen aus Fremden schnell Menschen mit einer gemeinsamen Geschichte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3adb725c-dd19-430c-9522-0dfd8285559a', 'de', 'Sie sagt, dass sie schlecht kocht. Was sind verspielte Antworten?', '["„Gibt’s bei dir dann Müsli zum Abendessen?“", "„Ist doch okay, Kochen ist halt nicht jedermanns Sache.“", "„Schade, ich koche viel.“", "„Wie schlecht? Lässt du Wasser anbrennen?“"]'::jsonb, 'Necken funktioniert, wenn es leicht bleibt und sie einlädt, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cfd9dfa-fc1f-49af-862d-aea72f90adc9', 'de', 'Sie meistert einen peinlichen Moment mit Charme und Humor. Was könntest du sagen?', '["„Wie du damit umgegangen bist, war richtig gut.“", "„Du bist perfekt.“", "„Du hast ein tolles Lächeln.“", "„Das war doch nichts.“"]'::jsonb, 'Das würdigt ihr soziales Geschick und wie sie in dem Moment reagiert hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('405b2702-ed84-4c3b-9a21-77729ea9f2d4', 'de', 'Sie schaut in die Karte und sagt: „Ich denk über alles viel zu lange nach.“ Beste freche Antwort?', '["„Das geht vielen so.“", "„Zwischen was überlegst du?“", "„Du kriegst das schon hin.“", "„Merkt man. Das ist ja auch eine Entscheidung über Leben und Tod.“"]'::jsonb, 'Übertreibung plus Wärme schafft Humor und Rhythmus, ohne dass du beeindrucken willst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('44e9bef3-c0f2-4d31-a3a2-481c50c7d9d5', 'de', 'Welche Sätze bringen wahrscheinlich Spannung rein?', '["„Lustige Geschichte.“", "„Erzähl mir mehr über deinen Job.“", "„Irgendwas hat dein Lächeln …“", "„Du hast eine richtig warme Ausstrahlung.“"]'::jsonb, 'Sanfte Beobachtungen zu ihrem Lächeln oder ihrer Ausstrahlung deuten Anziehung an und erzeugen ein leises Knistern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450fc086-463d-40c5-9ce4-77e9a664a8e7', 'de', 'Sie sagt: „Der Kaffee ist viel zu teuer.“ Was könntest du darauf sagen?', '["„Ja, die Preise sind überall verrückt.“", "„Mach ihn doch zu Hause.“", "„Aber du bist die Premiummischung eindeutig wert.“", "„Wie viel hat deiner gekostet?“"]'::jsonb, 'Ein freches Kompliment, verpackt in einen Witz, bringt Flirtenergie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4684c791-9598-4381-9511-739d9afdfead', 'de', 'Welche Reaktionen zeigen, dass dein Humor angekommen ist?', '["Sie lacht echt", "Sie korrigiert dich verspielt", "Sie macht selbst Witze", "Sie antwortet kurz und höflich"]'::jsonb, 'Wenn sie dabei ist und es erwidert, ist das grünes Licht. Kurze, höfliche Antworten sind es nicht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4962a3a5-8566-4b58-aafd-36f4a302ce53', 'de', 'Warum kann es die Anziehung schwächen, wenn du die ganze Zeit zu viel Abstand hältst?', '["Es kann Desinteresse oder Unsicherheit signalisieren", "Es wirkt unhöflich", "Es verwirrt sie", "Es bremst das Gesprächstempo"]'::jsonb, 'Deine Worte zeigen vielleicht Interesse, aber der Abstand signalisiert Zögern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49634200-5e42-4c7d-b10f-352eb5b017a0', 'de', 'Warum zählt beim ersten Flirten die Energie mehr als die Worte?', '["Sie schafft die Stimmung, auf die Menschen zuerst reagieren", "Warme, fröhliche Energie lässt andere sich leichter fühlen", "Wenig Energie signalisiert immer Selbstbewusstsein"]'::jsonb, 'Menschen fühlen sich zu positiven, mitreißenden Gefühlen hingezogen, bevor der Inhalt zählt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
